window.__BUNDLE__={"generatedAt":"2026-10-12T11:20:13.338810+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-10-05","archiveCutoff":"2021-10-13","addedToday":353,"addedThisRun":353,"fetchStats":{"hf":368,"arxiv":1473,"total":1841},"freshness":{"latestPaperDate":"2026-10-12","latestPublishedDate":"2026-10-12","latestBatchCount":316,"newInLast24h":353,"newInLast48h":353},"historyTotal":22848,"topicCounts":{"Multi-Agent":2650,"Evaluation":12416,"Planning":1734,"Memory":458,"Code Agent":909,"Interpretability":814,"Agentic RAG":1364,"Agentic Search":1776,"RL for LLM":1278,"Reasoning":6289,"Hallucination":1088,"Post-Training":2602,"Alignment":3037,"World Model":413,"Tool Use":1304,"Agent Safety":2498,"Computer Use":315,"Reflection":825,"VLM Training":1722,"LLM Training":2846,"Fine-tuning":3508,"Multimodal Agent":131,"Agent Framework":860,"Error Attribution":143,"Data Engine":472},"count":36,"recentTotal":2693,"archiveCount":0,"archiveTotal":20155,"sources":{"hf":86,"arxiv":2607,"semanticScholar":0},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"pdf":"https://arxiv.org/pdf/2610.12572.pdf","hfUrl":"https://huggingface.co/papers/2610.12572","date":"2026-10-12","title":"DiffusionART: Efficient, Stable and Scalable Reinforcement of Diffusion Models","id":"arxiv:2610.12572","arxiv":"https://arxiv.org/abs/2610.12572","submittedDate":"2026-10-08","topics":["Post-Training","Fine-tuning"],"upvotes":146,"tags":["Post-Training","Fine-tuning"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.12572","source":"hf","authors":["Zhenglin Wan","Jiayu Chen","Zhengfeiyang Zhang","Pengfei Zhou","Wangbo Zhao","Fangyuan Kong","Pengfei Wan","Kun Gai","Yang You"],"abstract":"Online reinforcement learning (RL) fine-tunes diffusion models with black-box rewards, but reverse-process methods such as Flow-GRPO are limited in efficiency by poor credit assignment, while forward-process methods such as DiffusionNFT are efficient yet unstable without carefully tuned exponential-moving-average (EMA) off-policy training. We show that NFT-style objectives contain a hidden forward--reverse consistency force that joint positive--negative training cancels only partially, and that EMA stabilizes training through restoration rather than off-policy rollouts. We introduce DiffusionART (Diffusion Reinforcement with Aggregation-First Reward Tilting), which aggregates each prompt's rewards into a shared reward-improving direction for reverse-process states, removing the consistency force by construction, and adds a trust-region-masked second update for drift-adaptive restoration "},{"pdf":"https://arxiv.org/pdf/2610.13527.pdf","hfUrl":"https://huggingface.co/papers/2610.13527","date":"2026-10-12","title":"S-Space: Exploring Spatial Workspace in Multimodal Language Models","id":"arxiv:2610.13527","arxiv":"https://arxiv.org/abs/2610.13527","submittedDate":"2026-10-09","topics":["Reasoning"],"upvotes":133,"tags":["Reasoning"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.13527","source":"hf","authors":["Zhiyuan Shi","Xiang Li","Xingzhuo Guo","Shangchen Miao","Weiliang Chen","Qiyu Dai","Jinshan Ren","Jiangran Lyu","Fangfu Liu","Mingsheng Long","Jialong Wu"],"abstract":"Multimodal language models (MLLMs) exhibit promising spatial reasoning capabilities, yet the internal mechanisms supporting them remain poorly understood. We uncover S-Space, a linear representation subspace in which object-token representations encode continuous coordinates along horizontal, vertical, and distance axes. Although we identify these axes by differentiating spatial-answer scores with respect to object-token activations, S-Space is intrinsic rather than induced by specific data or prompts, remaining readable under non-spatial questions. We show that S-Space functions as an internal spatial workspace of MLLMs. Perception encodes object locations into it, forming spatial representations that can be directly read out to support accurate spatial judgments. Internal reasoning transforms it for changing viewpoints. Verbal responses selectively access it, evidenced by causal interv"},{"pdf":"https://arxiv.org/pdf/2610.12611.pdf","hfUrl":"https://huggingface.co/papers/2610.12611","date":"2026-10-12","title":"SoftwareGym: Scaling Computer-Use Agent Training with Diverse Synthesized Software Environments","id":"arxiv:2610.12611","arxiv":"https://arxiv.org/abs/2610.12611","submittedDate":"2026-10-08","topics":["Evaluation"],"upvotes":64,"tags":["Evaluation"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.12611","source":"hf","authors":["Tian Jin","Wenhao Wang","Jing Kang","Haoting Shi","Rui Ye","Yijun Lu","Siheng Chen"],"abstract":"Computer-use agents (CUAs) are rapidly improving, yet synthesizing diverse and reliable software environments at scale remains challenging. Native application environments require substantial construction and integration effort, which limits application coverage and increases the risk of application-specific overfitting. Browser-hosted environments provide limited interaction depth and workflow complexity. These limitations motivate SoftwareGym, an automated pipeline for synthesizing GUI software environments with diverse interfaces, executable functionality, and runtime-verified behavior. It generates structurally diverse designs, realizes them as runnable applications, and uses GUI evaluation with iterative repair to ensure functional reliability. Using SoftwareGym, we synthesize 182 applications across twelve categories and achieve a mean GUI task pass rate of 91.5%. We construct Soft"},{"pdf":"https://arxiv.org/pdf/2610.13021.pdf","hfUrl":"https://huggingface.co/papers/2610.13021","date":"2026-10-12","title":"EmbodiedCLBench: Evaluating Continual Learning for Self-Evolving Embodied Agents","id":"arxiv:2610.13021","arxiv":"https://arxiv.org/abs/2610.13021","submittedDate":"2026-10-09","topics":["Evaluation"],"upvotes":56,"tags":["Evaluation"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.13021","source":"hf","authors":["Jie Huang","Yanan Chen","Ruixun Liu","Kaichen He","Xinyi He","Rui Huang","Zilong Zheng","Zhenliang Zhang","Yiwu Zhong"],"abstract":"Continual learning requires models to accumulate past experience and transfer it to new tasks. Despite substantial research on continual learning, existing work remains largely confined to non-embodied settings, without extending to embodied environments. To address this gap, we introduce EmbodiedCLBench, the first benchmark in embodied simulation for evaluating the continual learning capability of self-evolving agents. With compositional generalization as the core evaluation principle, our benchmark evaluates whether agents can first learn from basic tasks and then recombine the acquired skills to solve complex, unseen advanced tasks. Based on EmbodiedCLBench, we conduct extensive experiments across multiple agent harnesses and learning methods, revealing consistent limitations and distinctive behaviors. Our results show that while advanced tasks can be hardly solved under zero-shot set"},{"pdf":"https://arxiv.org/pdf/2610.13395.pdf","hfUrl":"https://huggingface.co/papers/2610.13395","date":"2026-10-12","title":"ProgramGym: Scaling Training Environments for Long-Horizon Program Reproduction Agents","id":"arxiv:2610.13395","arxiv":"https://arxiv.org/abs/2610.13395","submittedDate":"2026-10-09","topics":["LLM Training","Code Agent","Fine-tuning"],"upvotes":43,"tags":["LLM Training","Code Agent","Fine-tuning"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.13395","source":"hf","authors":["Chengyi Yang","Renxu Bao","Jue Hou","Zongpei Teng","Ziheng Wang","Yujie Lin","Chengsong Huang","Junnan Zhu","Delai Qiu","Yining Wang","Shengping Liu","Fei Long","Jinsong Su"],"abstract":"Coding agents are increasingly used to build programs from scratch as software engineers do rather than to resolve issues within a repository or to generate a repository from a given requirements document. However, scalable verifiable training environments that force agents to discover what is required and to decide how the system should be designed remain scarce. Moreover, existing agent workflows also cannot sustain long-horizon development in which the agent explores the reference program before implementation. To address these challenges, we introduce ProgramGym, a framework consisting of Program-Env and Program-Agent for scalable training environments of long-horizon program reproduction agents. Specifically, Program-Env constructs verifiable training environments from repositories through a feedback-driven loop that repairs runtime sandbox builds and the quality of black-box tests."},{"pdf":"https://arxiv.org/pdf/2610.12984.pdf","hfUrl":"https://huggingface.co/papers/2610.12984","date":"2026-10-12","title":"Work2Skill: Capturing Human GUI Experience for Reusable Agent Skill Induction","id":"arxiv:2610.12984","arxiv":"https://arxiv.org/abs/2610.12984","submittedDate":"2026-10-09","topics":["Evaluation"],"upvotes":34,"tags":["Evaluation"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.12984","source":"hf","authors":["Yuqi Huang","Hui Li","Yifei Cao","Zikun Cai","Tianci Xie","Yangfan Gao","Pinxue Guo","Chaoyun Zhang","Bingxuan Li","Rui Zheng","Hang Yan","Ning Liao"],"abstract":"Computer-use agents can perform increasingly complex GUI tasks, yet unfamiliar software and workflows requiring human domain knowledge remain challenging. Human demonstrations convey procedural knowledge through the same GUI interaction space, but reuse requires interpreting actions in context and separating workflow rules from task-specific details. We thus introduce Work2Skill, a framework that captures human GUI experience for reusable agent skill induction. WorkRecorder provides the framework's infrastructure for collecting this experience, aligning screen recordings, mouse and keyboard events, and available accessibility-tree information. Using WorkRecorder, we construct WorkDemo-350, the first synchronized multimodal dataset of human desktop GUI demonstrations for reusable agent skill induction and downstream evaluation. Its 350 demonstrations are screened for completeness and task"},{"pdf":"https://arxiv.org/pdf/2610.13113.pdf","hfUrl":"https://huggingface.co/papers/2610.13113","date":"2026-10-12","title":"Continually Post-training Small Models via Synthetic Self-distillation","id":"arxiv:2610.13113","arxiv":"https://arxiv.org/abs/2610.13113","submittedDate":"2026-10-09","topics":["Post-Training","Evaluation","Fine-tuning"],"upvotes":33,"tags":["Post-Training","Evaluation","Fine-tuning"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.13113","source":"hf","authors":["Woosung Koh","Hyunsoo Lee","Kyungjae Lee","Haeju Park","Dahyun Lee","Dasol Hwang","Moontae Lee"],"abstract":"Continual post-training faces a dual challenge of acquisition and retention: models must learn new capabilities while preserving prior knowledge. While Self-Distillation Fine-Tuning (SDFT) mitigates this using self-supervision with in-context demonstrations, it relies on strong in-context learning and instruction-following abilities. Consequently, SDFT fails on smaller models critical for low-latency, on-device use. To enable continual learning at smaller scales, we first identify the root cause of failure. We show that poor acquisition and forgetting correlate linearly with the post-trained model's distribution shift, revealing the necessity of in-distribution learning. We thus introduce Synthetic Self-Distillation (SynthSelf), imitating SDFT's in-distribution rewrite by outsourcing the task to a minimally larger, same-family aligner. Coupled with off-policy supervision and rejection sa"},{"pdf":"https://arxiv.org/pdf/2610.13912.pdf","hfUrl":"https://huggingface.co/papers/2610.13912","date":"2026-10-12","title":"RSI-Anything: Unlocking Recursive Self-Improvement with World Models","id":"arxiv:2610.13912","arxiv":"https://arxiv.org/abs/2610.13912","submittedDate":"2026-10-09","topics":["LLM Training","Planning","Evaluation","Reflection","World Model"],"upvotes":24,"tags":["LLM Training","Planning","Evaluation","Reflection","World Model"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.13912","source":"hf","authors":["Taoyong Cui","Pinxian Zeng","Wanghan Xu","Hao Xiao","Shuhan Xue","Qiang Gao","Wanli Ouyang","Pheng Ann Heng","Zhenfei Yin","Yingcheng Wu","Ling Yang"],"abstract":"Recursive self-improvement (RSI) aims to transform interaction experience into persistent improvements, yet external feedback is costly and world-model predictions may become unreliable as policies evolve. We introduce RSI-Anything, a domain-general framework built on JEPA-Anything that uses predictive world models to guide action and learning-data selection. Observed feedback drives policy or workflow improvement and conditional world-model adaptation, while component and compatibility checks govern the retention of updated policy-model pairs. Across diverse computational and scientific domains, RSI-Anything demonstrates substantial gains. In code repair, with the coder fixed, success increases from 26.3% with a static verifier to 29.2% through predictive selection and 31.2% after world-model adaptation, at comparable test usage. Graphical user interface (GUI) evaluations showed higher "},{"pdf":"https://arxiv.org/pdf/2610.13947.pdf","hfUrl":"https://huggingface.co/papers/2610.13947","date":"2026-10-12","title":"Towards Physically Grounded Articulated 3D Assets: A Multi-Agent Pipeline and Benchmark","id":"arxiv:2610.13947","arxiv":"https://arxiv.org/abs/2610.13947","submittedDate":"2026-10-09","topics":["Multi-Agent","Evaluation"],"upvotes":17,"tags":["Multi-Agent","Evaluation"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.13947","source":"hf","authors":["Xudong Cai","Ruijie Zhu","Haoliang Shang","Ruining Li","Marc Pollefeys","Shangzhe Wu","Andrea Vedaldi","Chuanxia Zheng"],"abstract":"In this paper, we study physically grounded articulated 3D asset generation---moving the goal from reproducing how objects look to capturing how they move and function. Inspired by the literature on procedural and agentic generation, we present Artisan, a system that extends the latest method Articraft by introducing a multi-agent pipeline with physical simulation feedback, enabling comprehensive attributes beyond geometry, appearance, and physically plausible articulation, such as collision-free motion, stability under gravity, and accurate mass and material properties. Furthermore, we construct a unified benchmark spanning four key aspects: spatial fidelity, physical plausibility, downstream task performance, and overall quality. The benchmark encompasses 100 reference assets from ArtVIP and LightWheel, 50 stability prompts, and 50 ABO objects with reference masses, with protocols eval"},{"pdf":"https://arxiv.org/pdf/2610.12570.pdf","hfUrl":"https://huggingface.co/papers/2610.12570","date":"2026-10-12","title":"Contextual Correction of Parallel Draftsfor Speculative Decoding","id":"arxiv:2610.12570","arxiv":"https://arxiv.org/abs/2610.12570","submittedDate":"2026-10-08","topics":["Reasoning","Evaluation"],"upvotes":16,"tags":["Reasoning","Evaluation"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.12570","source":"hf","authors":["Roy Eisenstadt","Harel Lidar","Tal Gonen","Omer Luxembourg","Itamar Zimerman","Lior Wolf","Eli David","Ilan Naiman"],"abstract":"Speculative decoding accelerates large language model inference by using a lightweight drafter to propose multiple tokens that are subsequently verified in parallel by the target model. Recent diffusion-based drafters make this paradigm particularly attractive: deep attention-based neural backbones provide strong predictions, while drafting multiple future positions in parallel avoids the sequential cost of autoregressive generation. This parallelism, however, comes at a cost. Tokens within a draft block are predicted without access to the realized identities of preceding draft tokens, removing intra-block dependencies that would naturally be available under autoregressive generation. We introduce DCOCO (DFlash Contextual Corrector), a lightweight mechanism that restores these dependencies while preserving parallel drafting. Rather than committing to each position's top prediction, DCOCO"},{"pdf":"https://arxiv.org/pdf/2610.13944.pdf","hfUrl":"https://huggingface.co/papers/2610.13944","date":"2026-10-12","title":"InstantFusion: A Shared Latent Interface for Heterogeneous Image Generators","id":"arxiv:2610.13944","arxiv":"https://arxiv.org/abs/2610.13944","submittedDate":"2026-10-09","topics":["Alignment"],"upvotes":16,"tags":["Alignment"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.13944","source":"hf","authors":["Xuanlang Dai","Jiazi Bu","Yujie Zhou","Yuhong Liu","Beichen Zhang","Penghui Yang","Ziyu Liu","Yuhang Zang"],"abstract":"Diffusion/flow models have emerged as the de facto paradigms for image generation, giving rise to a diverse family of modern generators with increasingly heterogeneous architectures and representations. Despite their remarkable generation capabilities, the cross-model alignment of latent representations and the consistency of their underlying denoising dynamics remain underexplored. In this work, we uncover an intriguing cross-model compatibility: independently trained generators exhibit similar latent spatial organization, while directly handing off intermediate states between unaligned models can still preserve coarse visual content. Motivated by these observations, we propose InstantFusion, a lightweight shared latent interface that connects the denoising trajectories of heterogeneous image generators. Specifically, to enable flexible cross-model state translation, model-specific Late"},{"pdf":"https://arxiv.org/pdf/2610.12569.pdf","hfUrl":"https://huggingface.co/papers/2610.12569","date":"2026-10-12","title":"SWE-Duel: Towards a Self-Scaling Arena for Coding Agents","id":"arxiv:2610.12569","arxiv":"https://arxiv.org/abs/2610.12569","submittedDate":"2026-10-08","topics":["LLM Training","Code Agent","Evaluation"],"upvotes":15,"tags":["LLM Training","Code Agent","Evaluation"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.12569","source":"hf","authors":["Wei Minn","Zhensu Sun","Lwin Khin Shar","David Lo"],"abstract":"Static coding benchmarks are fixed at release. Over time their tasks leak into training data, and stronger agents eventually saturate them. We argue that a benchmark should instead aim to be self-scaling: its tasks and oracles are created at evaluation time, so no content exists in advance to leak, and its difficulty is set by the participating agents rather than fixed at release. We introduce SWE-Duel, an arena in which two coding agents evaluate each other over mirrored Red-Blue turns. In each turn, the Red agent works on a real repository across three context-isolated sessions. It proposes and implements a new feature with feature tests, then embeds a subtle bug in that feature along with sealed bug-triggering tests. The resulting pull request is admitted only if (1) it passes the feature tests and the repository's existing tests while failing exactly the bug tests, and (2) a fresh se"},{"pdf":"https://arxiv.org/pdf/2610.12668.pdf","hfUrl":"https://huggingface.co/papers/2610.12668","date":"2026-10-12","title":"Recurrent Harness for Agentic Continual Learning","id":"arxiv:2610.12668","arxiv":"https://arxiv.org/abs/2610.12668","submittedDate":"2026-10-08","topics":["Evaluation","Reflection"],"upvotes":11,"tags":["Evaluation","Reflection"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.12668","source":"hf","authors":["Yuxin Xiao","Zhiyun Lu","Jianyu Wang","Yangtian Zhang","Yang Song","Qifan Wang","Bailin Wang"],"abstract":"Language model agents increasingly operate over long interaction streams, requiring online adaptation to distribution shifts through continual learning. However, existing agent harnesses typically either evolve their states only through forward information flow or rely on additional replay or validation data for harness optimization. To address this, we propose ReHarness, a recurrent harness framework for agentic continual learning that complements forward read and write with backward revision under a strictly online streaming protocol. We ask what information could have been captured differently in the harness state to better inform the current instance in the stream. Specifically, after each instance, we leverage the resulting trajectory as feedback to revise the reflections retrieved for that instance, thereby propagating feedback backward through the textual harness state. Across thr"},{"pdf":"https://arxiv.org/pdf/2610.12939.pdf","hfUrl":"https://huggingface.co/papers/2610.12939","date":"2026-10-12","title":"Surfing the Activation Wave: Analyzing the Information and Geometry of LLM Hidden States for Speculative Decoding","id":"arxiv:2610.12939","arxiv":"https://arxiv.org/abs/2610.12939","submittedDate":"2026-10-09","topics":["Evaluation","Alignment"],"upvotes":10,"tags":["Evaluation","Alignment"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.12939","source":"hf","authors":["Raghavv Goel","Sudhanshu Agrawal","Mukul Gagrani","Risheek Garrepalli","Mingu Lee"],"abstract":"Decoder hidden states from different layers of large language models (LLMs) often encode complementary information. However, existing speculative decoding methods typically rely on a small set of target-model layers chosen using fixed, position-based heuristics. Selecting an optimal subset of layers is inherently a combinatorial problem, making exhaustive evaluation infeasible even for moderately deep models. In this work, we present a principled framework for multi-layer hidden-state selection for speculative decoding based on two complementary criteria: informativeness, measured through matrix-entropy analysis, and diversity, quantified using centered kernel alignment (CKA). We investigate layer-wise Shannon entropy, aggregate entropy under hidden-state concatenation, and pairwise CKA dynamics across depth, revealing distinct geometric and informational compartments within decoder repr"},{"pdf":"https://arxiv.org/pdf/2610.13205.pdf","hfUrl":"https://huggingface.co/papers/2610.13205","date":"2026-10-12","title":"Rethinking Relative Policy Differences Transfer of On-Policy Distillation","id":"arxiv:2610.13205","arxiv":"https://arxiv.org/abs/2610.13205","submittedDate":"2026-10-09","topics":["LLM Training","Fine-tuning"],"upvotes":10,"tags":["LLM Training","Fine-tuning"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.13205","source":"hf","authors":["Rong Wu","Daocheng Fu","Yu Yang","Xuemeng Yang","Siqi Li","Shu Zou","Yao Zhu","Botian Shi","Bo Zhang","Cong Zhang","Pinlong Cai","Jianbiao Mei"],"abstract":"On-policy distillation (OPD) trains a target policy on its own rollouts using token-level supervision from a stronger teacher, but typically relies on the teacher being substantially more capable than the target. Recent work relaxes this requirement by transferring the relative policy difference between an expert and a reference policy rather than the expert's absolute distribution. Yet it remains unclear which differences provide useful supervision and which targets can benefit from them. We develop a unified view in which the log-probability ratio between a proxy expert and a proxy reference defines an implicit reward for KL-regularized policy optimization. This formulation induces an on-policy update for the target, recovers conventional OPD as a special case, and enables any-to-any transfer across models that differ in scale, training stage or generation. Our systematic experiments y"},{"pdf":"https://arxiv.org/pdf/2610.13171.pdf","hfUrl":"https://huggingface.co/papers/2610.13171","date":"2026-10-12","title":"PreSTO: Predictive Subtree Prefetching for Fast LLM Power Sampling","id":"arxiv:2610.13171","arxiv":"https://arxiv.org/abs/2610.13171","submittedDate":"2026-10-09","topics":["Reasoning"],"upvotes":9,"tags":["Reasoning"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.13171","source":"hf","authors":["Nan Jiang","Panagiotis Theodoropoulos","Wei Deng"],"abstract":"Power sampling improves large language model (LLM) reasoning at test time by sampling from a sharpened version of the base model's distribution. Its sampler, PowerMH, is slow because its Metropolis--Hastings (MH) updates are sequential: each accept/reject decision sets the state from which the next proposal is generated. Prior work reduces this cost by changing the sampler or the model (e.g., sequential Monte Carlo, approximate lookahead, distillation). We propose Predictive SubTree Prefetching (PreSTO), which accelerates PowerMH by prefetching future proposals and provably leaves its MH transition kernel unchanged. PreSTO views future MH outcomes as a tree of accept/reject decisions: in each model call, it generates the proposals of a \\textit{prefetched subtree} of this tree in one batch, then follows the realized path with the original MH acceptance rule. We also observe that MH reache"},{"pdf":"https://arxiv.org/pdf/2610.13627.pdf","hfUrl":"https://huggingface.co/papers/2610.13627","date":"2026-10-12","title":"AMLworld-Compact: Importance-Weighted Downsampling for Cost-Effective LLM Evaluation and Error Diagnosis","id":"arxiv:2610.13627","arxiv":"https://arxiv.org/abs/2610.13627","submittedDate":"2026-10-09","topics":["Evaluation"],"upvotes":9,"tags":["Evaluation"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.13627","source":"hf","authors":["Natapong Nitarach","Phume Ngampornsukswadi","Pittawat Taveekitworachai","Surapon Nonesung","Warit Sirichotedumrong","Kunat Pipatanakul"],"abstract":"Evaluating large language models (LLMs) on AMLworld's smallest test splits is costly because each of over a million targets requires a separate graph prompt. Sampling reduces this cost, but small balanced subsets change unweighted precision and F1. We introduce AMLworld-Compact, an evaluation set that retains every illicit test transaction and samples benign transactions from supervised-score strata. Its HT-Coreset protocol reduces evaluation targets by 271x and 611x on HI-Small and LI-Small. Horvitz-Thompson weights give unbiased full-test confusion-count estimates for fixed predictions; recall is exact, while precision and F1 are ratio estimates. In a held-out study using Graph Feature Preprocessor (GFP) features, one boosted-tree family defines strata for evaluating the other over 500 draws per configuration. At the released sizes, F1 RMSE is 0.00-2.58 percentage points versus 4.44-7."},{"pdf":"https://arxiv.org/pdf/2610.13330.pdf","date":"2026-10-12","title":"Masked Diffusion Language Agents for Tool-Integrated Chemical Reasoning","id":"arxiv:2610.13330","arxiv":"https://arxiv.org/abs/2610.13330","submittedDate":"2026-10-09","topics":["Post-Training","LLM Training","Tool Use","Reasoning","Planning","Evaluation","Fine-tuning"],"upvotes":0,"tags":["Post-Training","LLM Training","Tool Use","Reasoning","Planning"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.13330","source":"arxiv","authors":["Mengdi Liu","Chenghao Jia","Hong Chang","Shiguang Shan"],"abstract":"Designing tool-integrated reasoning agent systems for complex chemical tasks remains a fundamental challenge. Although recent chemical agents have demonstrated promising performance through the integration of external tools, they are still built on the autoregressive paradigm, which is inherently constrained by causal attention and left-to-right generation. As a result, they often struggle with bidirectional molecular understanding, global coordinated tool planning and multi-source evidence integration. To address this challenge, we introduce ChemDiffAgent, the first masked diffusion language agent for tool-integrated chemical reasoning. It reformulates chemical reasoning as iterative denoising over interleaved reasoning and tool-use trajectories, enabling tool-use decisions to be jointly determined under full-trajectory context and thereby better aligning the agent's decision boundary w"},{"pdf":"https://arxiv.org/pdf/2610.13356.pdf","date":"2026-10-12","title":"SWE-Critix: Post-Training Generalist Verifiers for Assessing Coding-Agent Trajectories","id":"arxiv:2610.13356","arxiv":"https://arxiv.org/abs/2610.13356","submittedDate":"2026-10-09","topics":["Post-Training","LLM Training","Reasoning","Code Agent","Fine-tuning","RL for LLM"],"upvotes":0,"tags":["Post-Training","LLM Training","Reasoning","Code Agent","Fine-tuning"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.13356","source":"arxiv","authors":["Jiajun Hu","Chun Yong Chong"],"abstract":"Coding agents are increasingly deployed for end-to-end software engineering tasks, where a readily available oracle evaluator that defines the success criteria is often absent. This motivates verifications for coding agents that can reliably judge and explain their behavior. However, verification is non-trivial as coding agents are increasingly capable of solving long-horizon software engineering tasks. Their execution trajectories can be extremely long, containing hundreds of iterative interactions with code repositories and external tools. Existing verifiers either rely on general-purpose LLMs without specialized training or train dedicated critics that predominantly focus on producing scalar rewards, highlighting the relatively limited exploration of training-based generalist verification. We introduce SWE-Critix, a post-training pipeline for training generalist verifiers of coding-ag"},{"pdf":"https://arxiv.org/pdf/2610.13594.pdf","date":"2026-10-12","title":"MENTOR: Learning from Failure with On-Policy Pedagogical Intervention","id":"arxiv:2610.13594","arxiv":"https://arxiv.org/abs/2610.13594","submittedDate":"2026-10-09","topics":["Error Attribution","Post-Training","Multi-Agent","Reasoning","RL for LLM","Agent Framework"],"upvotes":0,"tags":["Error Attribution","Post-Training","Multi-Agent","Reasoning","RL for LLM"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.13594","source":"arxiv","authors":["Guanlan Yue","Hang Yu","Xiaoyong Huang","Ruipeng Li","Wei Zhang","Bingchang Liu","Rui Wang"],"abstract":"Reinforcement Learning from Verifiable Rewards (RLVR) is a key driver for Large Reasoning Models, but it is vulnerable to \"zero-reward collapse\", a training failure where a sudden increase in task difficulty causes the learning signal to vanish. We argue that the conventional approach of discarding these failed trajectories is wasteful, as they contain valuable diagnostic information about the model's cognitive gaps, a bright side that can be leveraged for recovery. Existing solutions, however, often regress to static, \"off-policy-style\" interventions like pre-defined hint libraries or perform post-hoc refinement, failing to provide the adaptive, forward-looking guidance needed to escape the collapse. To address this, we propose a paradigm shift towards on-policy pedagogical intervention and introduce MENTOR, a multi-agent framework that acts as a live mentor. MENTOR diagnoses the root c"},{"pdf":"https://arxiv.org/pdf/2610.12957.pdf","date":"2026-10-12","title":"JoyInside-VLM-Agent: Product-Conditioned Multimodal Policy Learning for Embodied Agents","id":"arxiv:2610.12957","arxiv":"https://arxiv.org/abs/2610.12957","submittedDate":"2026-10-09","topics":["LLM Training","VLM Training","Planning","Evaluation","Fine-tuning","Multimodal Agent"],"upvotes":0,"tags":["LLM Training","VLM Training","Planning","Evaluation","Fine-tuning"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.12957","source":"arxiv","authors":["Gangyi Li","LuYao Wang","Jingfu Sun","Jingyi Yuan","Hang Liu","Hao Zong","Yujia Hu","Tingting Gao","Jianyong Wang","Xu Yang"],"abstract":"Embodied agents must translate multimodal observations and user requests into executable actions while adapting to product constraints, changing goals, and execution feedback. We present JoyInside-VLM-Agent, a ReAct-style multimodal agent developed through product-conditioned trajectory construction and staged policy learning for robotic platforms and smart hardware. A closed-loop sandbox generates multimodal interaction trajectories covering goal revisions and failure recovery, which are checked against execution outcomes and semantic criteria. Supervised fine-tuning and multi-teacher on-policy distillation precede reinforcement learning with DPER (Dual-Source Privileged On-Policy Self-Distillation with Token-Level Evidence Routing). DPER routes token-level evidence between a frozen privileged teacher and a privileged student sharing the rollout policy's parameters, modulating reward-de"},{"pdf":"https://arxiv.org/pdf/2610.12830.pdf","date":"2026-10-12","title":"Cross-Behavior Policy Optimization: Unified Learning from Offline Demonstrations and On- and Off-Policy Rollouts via a Shared Regression Target","id":"arxiv:2610.12830","arxiv":"https://arxiv.org/abs/2610.12830","submittedDate":"2026-10-09","topics":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"upvotes":0,"tags":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.12830","source":"arxiv","authors":["Du Cheng","Junyu Lu","Jingfan Zhang","Yuzhuo Zhang","Haoxuan Jia","Shichao Weng"],"abstract":"Reasoning post-training draws on offline demonstrations and policy-generated rollouts, yet conventional supervised fine-tuning (SFT) followed by reinforcement learning (RL) separates their objectives and limits continued reuse of collected responses. We propose \\textbf{Cross-Behavior Policy Optimization} (CBPO), which makes these sources compatible with one regression loss through a fixed-reference target. Because the generating policy does not enter this target, positive and negative offline completions, reference responses, and current and historical rollouts can share a common reward-labeled record format and replay buffer. As new responses enter the buffer, optimization retains the same regression objective without coordinating separate SFT and RL objectives or requiring stored behavior-policy probabilities, importance weighting, or a learned critic. Restricting the available sources"},{"pdf":"https://arxiv.org/pdf/2610.12866.pdf","date":"2026-10-12","title":"CaptchaAgent: Verifiable Visual Reasoning for CAPTCHA Solving","id":"arxiv:2610.12866","arxiv":"https://arxiv.org/abs/2610.12866","submittedDate":"2026-10-09","topics":["Agentic Search","VLM Training","Reasoning","Computer Use","Hallucination","Evaluation"],"upvotes":0,"tags":["Agentic Search","VLM Training","Reasoning","Computer Use","Hallucination"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.12866","source":"arxiv","authors":["Shangquan Sun","Ruoyu Chen","Zhirui Liu","Xiang Liu","Chenghao Qian","Wenqi Ren","Xiaochun Cao"],"abstract":"Modern reasoning CAPTCHAs require fine-grained perception, compositional relation reasoning, and grounded browser interaction. End-to-end vision-language model agents remain brittle in this setting because a missed object, incorrect count, or confused relation can propagate directly to the final action. To address this problem, we present CaptchaAgent, a structured visual reasoning framework for interactive CAPTCHA solving. Instead of predicting an action directly from a screenshot, CaptchaAgent first constructs a visual intermediate representation (V-IR) that explicitly records entities, attributes, and spatial or topological relations. A symbol-only ASCII protocol further requires the parser to commit to a concrete object set and count. Building on this global representation, localized evidence refinement revisits ambiguous regions at higher effective resolution, while counterfactual c"},{"pdf":"https://arxiv.org/pdf/2610.13510.pdf","date":"2026-10-12","title":"Retrieval-Augmented Multimodal Language Model with Heterogeneous Evidence Integration for Clinical Prognosis","id":"arxiv:2610.13510","arxiv":"https://arxiv.org/abs/2610.13510","submittedDate":"2026-10-09","topics":["Agentic Search","LLM Training","Memory","Evaluation","Fine-tuning"],"upvotes":0,"tags":["Agentic Search","LLM Training","Memory","Evaluation","Fine-tuning"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.13510","source":"arxiv","authors":["Hamza Shafiq","Jialu Tang","Ting Dang","Jun Hu","Aaqib Saeed"],"abstract":"Clinical prognosis requires integrating structured measurements, physiological waveforms, longitudinal history, and population context. We introduce PRISM (Population-Retrieved Inference for Structured Multimodal Prognosis), a multimodal language model that combines per-feature numerical tokenization, recency-weighted aggregation of longitudinal ECGs, and a dual-modality population memory bank. Retrieval operates in representation space: the model receives mean-pooled embeddings of similar training-cohort encounters, while no individual retrieved record enters the prompt. On the 1,443-task MDS-ED benchmark, PRISM achieves AUROCs of 86.2% for diagnosis, 93.1% for deterioration, 91.8% for ICU admission, and 92.8% for mortality. These results use a 96-hour pre-arrival window unavailable to reported baselines. With benchmark-window inputs only, PRISM reaches 0.8895 AUROC, compared with 0.893"},{"pdf":"https://arxiv.org/pdf/2610.13438.pdf","date":"2026-10-12","title":"Rollout-Time Intervention: Unlocking Agentic Reinforcement Learning Beyond Policy Limits","id":"arxiv:2610.13438","arxiv":"https://arxiv.org/abs/2610.13438","submittedDate":"2026-10-09","topics":["Tool Use","Reasoning","Planning","Evaluation","RL for LLM"],"upvotes":0,"tags":["Tool Use","Reasoning","Planning","Evaluation","RL for LLM"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.13438","source":"arxiv","authors":["Chen Xi","Ding Ruixue","Wang Zhigaoyuan","Zhang Fanrui","Zhang Qiang","Chen Boli","Wang Shihang","Wang Tianfu","Ren Ailin","Wang Pengyong","Xie Pengjun","Xiong Hui"],"abstract":"Reinforcement learning (RL) has emerged as a key paradigm for improving large language model (LLM) agents, enabling stronger reasoning, planning, and tool-use in interactive environments. However, existing agent RL methods remain fundamentally constrained by an on-policy reasoning bottleneck: when tasks exceed the model's current capability boundary, effective trajectories become extremely sparse and training often collapses. We introduce Rollout-Time Intervention (RTI), a technique designed to elicit successful trajectories beyond the policy's intrinsic exploration capacity. RTI operates by leveraging reward-side evidence (i.e., evaluation rubrics) during rollout to convert erroneous trajectories into successful ones, providing effective learning signals for tasks that the policy rarely solves on its own. Although intervention trajectories are inherently off-policy, we find that they ca"},{"pdf":"https://arxiv.org/pdf/2610.13152.pdf","date":"2026-10-12","title":"Quality, Not Just Outcome: A Structural Scoring Framework for Selecting Coding-Agent Trajectories for Supervised Fine-Tuning","id":"arxiv:2610.13152","arxiv":"https://arxiv.org/abs/2610.13152","submittedDate":"2026-10-09","topics":["LLM Training","Code Agent","Evaluation","Alignment","Fine-tuning"],"upvotes":0,"tags":["LLM Training","Code Agent","Evaluation","Alignment","Fine-tuning"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.13152","source":"arxiv","authors":["Sida Li","Yuanxin Liu","Shicheng Li","Linli Yao","Xu Sun","Haoli Bai","Xiaohui Li"],"abstract":"Open coding agents are commonly trained through supervised fine-tuning on interaction trajectories whose final patches pass the benchmark test suite. However, this outcome-level filtering criterion ignores process quality: trajectories that eventually succeed may still contain inefficient interaction patterns such as repetitive file inspection, unstable tool usage, or delayed modification behavior, all of which become part of the imitation target. We propose TQS (Trajectory Quality Score), a structural scoring framework for coding-agent trajectories that operates directly on trajectory structure, requires no LLM judge, and runs in linear time. TQS characterizes trajectory quality through structural signals organized around structured convergence: information focus, intent--action alignment, and policy dynamics. Using 155,144 successful trajectories from a public open-license corpus, we r"},{"pdf":"https://arxiv.org/pdf/2610.12914.pdf","date":"2026-10-12","title":"OGPO: Offline Goal-conditioned Policy Optimization for Recoverable Vision-Language-Action Models","id":"arxiv:2610.12914","arxiv":"https://arxiv.org/abs/2610.12914","submittedDate":"2026-10-09","topics":["Post-Training","LLM Training","VLM Training","Evaluation","Fine-tuning"],"upvotes":0,"tags":["Post-Training","LLM Training","VLM Training","Evaluation","Fine-tuning"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.12914","source":"arxiv","authors":["Xule Gao","Xi Wang","Zehua Zang","Rui Wang","Changwen Zheng","Chuxiong Sun"],"abstract":"Vision-language-action (VLA) models have shown strong promise in robotic manipulation, yet their post-training still predominantly relies on trajectory-level supervised imitation over robot demonstrations. While effective for learning feasible actions, this paradigm supervises policies to reproduce expert actions at each step, biasing them toward demonstration-specific action paths and providing limited guidance for recovering toward task-progress states once execution deviates from demonstrated trajectories. To address this limitation, we propose OGPO, an Offline Goal-conditioned Policy Optimization framework for recoverable VLA post-training. Instead of treating offline demonstrations merely as step-wise action labels, OGPO adaptively relabels trajectories with semantic key states and constructs goal-conditioned process rewards to optimize the policy for reaching these task-progress st"},{"pdf":"https://arxiv.org/pdf/2610.12707.pdf","date":"2026-10-12","title":"Unsupervised Multimodal Reward Modeling","id":"arxiv:2610.12707","arxiv":"https://arxiv.org/abs/2610.12707","submittedDate":"2026-10-08","topics":["Post-Training","VLM Training","Hallucination","Evaluation","Fine-tuning"],"upvotes":0,"tags":["Post-Training","VLM Training","Hallucination","Evaluation","Fine-tuning"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.12707","source":"arxiv","authors":["Yueying Li","Jingxuan Fan","Kianté Brantley","Sham M. Kakade","Hanlin Zhang"],"abstract":"Vision-language reward models are trained on annotated preference pairs, which are expensive to collect, can disagree, and are ranked by benchmark accuracy. We build one with no human preference label: a linear head on an intermediate layer of a frozen Qwen3-VL backbone, trained to score a web caption above a perturbed version of the same caption; labeled data enters only to select the layer. The layer is the decisive choice, worth 5.8 points over the last layer, and one recipe transferred without re-tuning beats or at least matches GPT-4o on three benchmarks at 32B, 6.6 points ahead on VL-RewardBench, from a few thousand parameters at about a thousandth of fine-tuning compute. At an equal pair budget, perturbations teach a frozen head 3 to 5 points more than curated RLAIF-V pairs. Because the backbone is frozen, the objective is convex, and the perturbation sampler specifies the reward,"},{"pdf":"https://arxiv.org/pdf/2610.12995.pdf","date":"2026-10-12","title":"What Should SFT Learn? Conditional Information Gain for Generalizable Post-Training","id":"arxiv:2610.12995","arxiv":"https://arxiv.org/abs/2610.12995","submittedDate":"2026-10-09","topics":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"upvotes":0,"tags":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.12995","source":"arxiv","authors":["Yuxuan Gu","Kequan Niu","Xiaocheng Feng","Yun Li","Yiqiao Yang","Bing Qin"],"abstract":"Supervised fine-tuning (SFT) remains a widely used approach for post-training large language models, because fixed demonstrations can directly introduce desired reasoning strategies and behavioral patterns. Yet forcing a model to imitate externally provided trajectories may also interfere with behaviors already supported by pretraining, limiting generalization beyond the training distribution. Recent dynamic SFT methods mitigate this issue by reweighting token-level supervision according to model-side signals such as predictive probability, prior support, or distributional compatibility. However, model compatibility is not equivalent to learning value: a token that is weakly supported by the current model may either be an undesirable mismatch or precisely the task-specific decision that the demonstration is intended to teach. We propose CIG-SFT, an information-theoretic framework that es"},{"pdf":"https://arxiv.org/pdf/2610.13672.pdf","date":"2026-10-12","title":"Inject a Turn, Not a Token: Learning Where to Redirect LLM Reasoning for Self-Correction","id":"arxiv:2610.13672","arxiv":"https://arxiv.org/abs/2610.13672","submittedDate":"2026-10-09","topics":["Post-Training","Reasoning","Evaluation","Fine-tuning","Reflection"],"upvotes":0,"tags":["Post-Training","Reasoning","Evaluation","Fine-tuning","Reflection"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.13672","source":"arxiv","authors":["Jiwon Jeon","Myungsik Cho","Jeonghye Kim","Youngchul Sung"],"abstract":"Large language models struggle to reliably identify and correct errors in their own reasoning. Unlike prior training-based approaches that fine-tune an LLM to generate revisions or feedback, we learn where to intervene in failed rollouts and determine how to redirect them. To choose where to intervene, we train a 130K-parameter MLP head on a frozen encoder using only final-answer correctness. For redirection, we find that under a fixed generation budget, the tested inline injections fail to reliably redirect reasoning, whereas presenting the same instruction in a new user turn changes the model's course. The resulting correction framework, UPTURN (User-Prompt TURN injection at a learned position), requires no LLM fine-tuning: it retains a selected prefix, injects an instruction as a new user turn, and regenerates the suffix. Across four reasoners and six math benchmarks, UPTURN improves "},{"pdf":"https://arxiv.org/pdf/2610.12757.pdf","date":"2026-10-12","title":"MADS: Multi-Agent Dialog Simulation for Robust Conversational Agents","id":"arxiv:2610.12757","arxiv":"https://arxiv.org/abs/2610.12757","submittedDate":"2026-10-08","topics":["LLM Training","Multi-Agent","Evaluation","Fine-tuning","Data Engine"],"upvotes":0,"tags":["LLM Training","Multi-Agent","Evaluation","Fine-tuning","Data Engine"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.12757","source":"arxiv","authors":["Arkajyoti Chakraborty","Adam Zernik","Ishika Kulkarni","Mudit Arora","Hugo Lin","Justin Chiu","Alessandro Di Bari","Neha Gupta","Andreas Stolcke"],"abstract":"Task-oriented conversational agents remain fragile under realistic conditions, especially when users exhibit non-cooperative behavior. Existing function-calling benchmarks underrepresent adversarial conversation trajectories, thereby limiting the training resources available for developing robust agents. We present MADS (Multi-Agent Dialog Simulation), a synthetic data generation pipeline that produces structured, diverse dialogue trajectories. We inject adversarial conversation, producing validated conversation trajectories that capture realistic, unhappy paths. Using MADS, we construct MADS-Bench: a benchmark spanning six domains, 55 personas, and 1095 conversations, with approximately 66% of conversations containing failure-prone conversation scenarios. We evaluate the robustness of the trained models using a two-stage training approach that combines supervised fine-tuning (SFT) and r"},{"pdf":"https://arxiv.org/pdf/2610.13790.pdf","date":"2026-10-12","title":"OccludeBench: Can VLMs Find What's Missing?","id":"arxiv:2610.13790","arxiv":"https://arxiv.org/abs/2610.13790","submittedDate":"2026-10-09","topics":["VLM Training","Tool Use","Reasoning","Evaluation","Reflection"],"upvotes":0,"tags":["VLM Training","Tool Use","Reasoning","Evaluation","Reflection"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.13790","source":"arxiv","authors":["Jasin Cekinmez","Addison J. Wu","Ryo Mitsuhashi","Linrong Cai","Xingyu Fu","Zhuang Liu"],"abstract":"How well can vision-language models (VLMs) reason about what is missing from an image? We study this question with OccludeBench, a manually curated benchmark for recovering fully occluded objects from the visual evidence that remains. OccludeBench distinguishes direct cases, where the hidden object must be recovered from a specific physical cue such as a shadow or reflection, from inferential cases, where it can be inferred from broader scene context. Across five VLMs, accuracy averages 42.7% on direct cases versus 62.7% on inferential cases, exhibiting a 20.0-point gap. Humans attain higher accuracies of 63.4% versus 68.5% for direct and inferential images, respectively, with no significant gap. To locate this failure, we introduce OccludeTrace, a four-stage diagnostic that isolates where the visual reasoning process breaks down. The bottleneck emerges when models must recover the relev"},{"pdf":"https://arxiv.org/pdf/2610.13166.pdf","date":"2026-10-12","title":"Scaling Agentic Data for Long-Horizon Terminal Intelligence","id":"arxiv:2610.13166","arxiv":"https://arxiv.org/abs/2610.13166","submittedDate":"2026-10-09","topics":["LLM Training","Reasoning","Evaluation","Fine-tuning","Data Engine"],"upvotes":0,"tags":["LLM Training","Reasoning","Evaluation","Fine-tuning","Data Engine"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.13166","source":"arxiv","authors":["Shun Zou","Ziyu Ma","Yi Zou","Yong Wang","Lin Chen","Zehui Chen","Guanhua Chen","Xiangxiang Chu","Feng Zhao"],"abstract":"Terminal agents are moving beyond local operations toward completing real-world professional tasks. Short trajectories can demonstrate commands and tool calls, but they do not fully show how agents accumulate evidence through exploration, use it to inform judgments, continually adjust strategies based on feedback, and turn intermediate results into final deliverables. High-quality long-horizon trajectories capture these agentic behavioral patterns and their connections within a single problem-solving process, providing richer experience for sustained autonomous work. However, environment synthesis may complete or simplify the key work underlying these patterns in advance and thus remove the need for exploration, implementation, and verification that the agent was meant to perform. To address this, we introduce TerminalHorizon, a fully automated data synthesis engine for long-horizon term"},{"pdf":"https://arxiv.org/pdf/2610.13184.pdf","date":"2026-10-12","title":"AdaC-GRPO: Towards Mastering Long-Horizon Visual Sudoku Puzzles via Adaptive Curriculum Learning","id":"arxiv:2610.13184","arxiv":"https://arxiv.org/abs/2610.13184","submittedDate":"2026-10-09","topics":["Post-Training","Reasoning","Evaluation","RL for LLM"],"upvotes":0,"tags":["Post-Training","Reasoning","Evaluation","RL for LLM"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.13184","source":"arxiv","authors":["Sida Li","Yuanxin Liu","Linli Yao","Shicheng Li","Xu Sun","Haoli Bai","Xiaohui Li"],"abstract":"While reinforcement learning with verifiable reward (RLVR) enhances reasoning in large language models, its efficacy in long-horizon multimodal tasks remains underexplored. Visual Sudoku puzzles pose a representative challenge, requiring multi-step deductive reasoning over both local constraints and global dependency chains. To this end, we introduce FG-Sudoku, a fine-grained benchmark categorized by grid size and required deductive steps. Evaluations reveal that frontier MLLMs fail on complex long-range dependencies (e.g., 9*9 puzzles). During post-training, this near-zero success rate causes severe reward sparsity, halting standard RLVR. We propose Adaptive Curriculum Group Relative Policy Optimization (AdaC-GRPO) to overcome this. Unlike rigid or prior-based schedules, AdaC-GRPO dynamically constructs training batches by tracking the model's \"Zone of Proximal Development\" via online r"},{"pdf":"https://arxiv.org/pdf/2610.13832.pdf","date":"2026-10-12","title":"SpatialASM: Internalizing Active Mentalization for Spatial Reasoning","id":"arxiv:2610.13832","arxiv":"https://arxiv.org/abs/2610.13832","submittedDate":"2026-10-09","topics":["VLM Training","Reasoning","Planning","Evaluation"],"upvotes":0,"tags":["VLM Training","Reasoning","Planning","Evaluation"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.13832","source":"arxiv","authors":["Yuhong Liu","Shenxi Wu","Junyi Chi","Beichen Zhang","Xuanlang Dai","Jiaqi Wang","Yuhang Zang","Dahua Lin"],"abstract":"When solving complex spatial reasoning tasks, ordinary humans naturally revisit the scenes from task-relevant viewpoints and mentally reconstruct the spatial layouts from those viewpoints. But can Large Vision-Language Models (LVLMs) proactively think in the same way? We term this ability Active Spatial Mentalization (ASM), an intrinsic component of visual intelligence that remains substantially underdeveloped in current LVLMs. To bridge this gap, we introduce SpatialASM, a scalable framework to internalize ASM into LVLMs through training-time spatial simulation. SpatialASM employs an allocentric novel-view generator to ground hypothetical viewpoints in visual evidence and produces two complementary forms of supervision: i) explicit ASM trajectories that teach LVLMs when and how to adaptively invoke view planning and imagination during spatial reasoning, and ii) automatically-constructed"},{"pdf":"https://arxiv.org/pdf/2610.12933.pdf","date":"2026-10-12","title":"Learning More by Training Less: Uncertainty-Guided Progressive Contraction for Efficient Reasoning Post-Training","id":"arxiv:2610.12933","arxiv":"https://arxiv.org/abs/2610.12933","submittedDate":"2026-10-09","topics":["Post-Training","LLM Training","Reasoning","Evaluation"],"upvotes":0,"tags":["Post-Training","LLM Training","Reasoning","Evaluation"],"announceDate":"2026-10-12","url":"https://arxiv.org/abs/2610.12933","source":"arxiv","authors":["Suorong Yang","Jiaxin Wang","Jiaming Su","Chentao Yue","Furao Shen","Peng Ye","Soujanya Poria"],"abstract":"Large language models have achieved remarkable advances in complex reasoning. However, scaling reasoning post-training with ever-larger corpora can substantially increase training cost without proportional performance gains. In this study, we therefore ask: how far can reasoning supervision be compressed without sacrificing capability? To this end, we propose an uncertainty-guided progressive contraction framework that concentrates supervision and optimization on the reasoning trajectories most valuable for learning. Specifically, rather than treating a teacher-generated chain-of-thought (CoT) as a single realized path, we construct uncertainty-profiled reasoning supervision by building Monte Carlo reasoning trees around intermediate reasoning states to expose process-level uncertainty. This uncertainty first contracts the original corpus into a compact teacher-informed pool. A second, l"}],"archive":[],"latestPath":"data/latest.json"};
